#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {internal static class SettingsSurfacesTests {
 internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();var windows=new List<Window>();string motif=AppearanceTheme.Motif,mode=AppearanceTheme.Mode;Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);checks.Add(message);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs-CZ");FluentTheme.Ensure();
 foreach(string style in new[]{"Original","Balanced"}){AppearanceTheme.SetMotif(style);AppearanceTheme.Apply("Light");foreach(NetworkProtocol protocol in Enum.GetValues(typeof(NetworkProtocol))){var dialog=new NetworkProfileDialog(null,new NetworkProfile{Name="Test profilu",Host="fixture.invalid",Protocol=protocol});windows.Add(dialog);Open(dialog);check(!FluentUiTests.Children<Button>(dialog).Any(x=>Convert.ToString(x.Content)==L.Text("network.openAdvancedTab")),"profile has no duplicate Advanced button in its form");var more=FluentUiTests.Children<Button>(dialog).Single(x=>System.Windows.Automation.AutomationProperties.GetAutomationId(x)=="CleanMore");check(more.IsVisible&&more.TranslatePoint(new Point(),dialog).X<dialog.ActualWidth/2,"profile More is visible at the left of the footer");more.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(Convert.ToString(dialog.Tabs.Tag)=="clean-options-expanded","profile More opens the sidebar");for(int i=0;i<2;i++){dialog.Tabs.SelectedIndex=i;NavigationTests.Wait(Task.Delay(40));dialog.FitProfilePage();check(FluentUiTests.Children<TextBlock>(dialog).Any(x=>x.FontSize==20&&x.IsVisible),style+" "+protocol+" "+i+": shared header present");var ok=FluentUiTests.Children<Button>(dialog).Single(x=>Convert.ToString(x.Content)=="OK");var frame=(FrameworkElement)dialog.Content;check(ok.TransformToAncestor(frame).Transform(new Point(0,ok.ActualHeight)).Y<=frame.ActualHeight,style+" "+protocol+" "+i+": profile actions remain visible");NextStageTests.Draw(dialog,Path.Combine(root,style+"-"+protocol+"-"+i+".png"));}dialog.Close();windows.Remove(dialog);}
 foreach(var package in ArchivePluginInstaller.Packages){var plugin=new ArchivePluginWindow(null,package,delegate{});windows.Add(plugin);Open(plugin);check(FluentUiTests.Children<TextBlock>(plugin).Any(x=>x.FontSize==20),style+": plugin window has shared header "+package.Id);NextStageTests.Draw(plugin,Path.Combine(root,style+"-plugin-"+package.Id+".png"));plugin.Close();windows.Remove(plugin);}
 AppearanceTheme.Apply("Dark");var dark=new ConfigurationDialog(null);windows.Add(dark);Open(dark);for(int i=0;i<7;i++){dark.Sections.SelectedIndex=i;NavigationTests.Wait(Task.Delay(30));dark.FitSettingsPage();check(FluentUiTests.Children<Button>(dark).Any(x=>Convert.ToString(x.Content)==L.Text("action.save")&&x.IsVisible),style+" dark page "+i+": save remains available");NextStageTests.Draw(dark,Path.Combine(root,style+"-dark-"+i+".png"));}dark.VerifyPanelsForTests(check);NextStageTests.Draw(dark,Path.Combine(root,style+"-panels.png"));dark.Close();windows.Remove(dark);
 }File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;}catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{foreach(var window in windows)window.Close();AppearanceTheme.SetMotif(motif);AppearanceTheme.Apply(mode);}}
 static void Open(Window w){w.WindowStartupLocation=WindowStartupLocation.Manual;w.Left=-18000;w.Top=-18000;w.ShowActivated=false;w.ShowInTaskbar=false;w.Show();NavigationTests.Wait(Task.Delay(100));w.UpdateLayout();}
}}
namespace FileCompass {
 public sealed partial class ConfigurationDialog {
  internal void VerifyPanelsForTests(Action<bool,string> check){
   Sections.SelectedItem=L.Text("settings.panelsSection");NavigationTests.Wait(Task.Delay(60));FitSettingsPage();
   check(sizeUnits.IsVisible&&showHidden.IsVisible&&showSystem.IsVisible,"size units and hidden/system visibility share the dedicated Panels settings page");
   sizeUnits.SelectedIndex=2;showHidden.IsChecked=false;showSystem.IsChecked=true;SaveChanges();var saved=ProgramSettings.Load();check(saved.SizeUnits=="Bytes"&&!saved.ShowHiddenFiles&&saved.ShowSystemFiles,"Panels settings save exact byte units and independent visibility choices");
   sizeUnits.SelectedIndex=0;SaveChanges();check(ProgramSettings.Load().SizeUnits=="SI","Panels settings save MB/GB units");sizeUnits.SelectedIndex=1;SaveChanges();check(ProgramSettings.Load().SizeUnits=="IEC","Panels settings save MiB/GiB units");
  }
 }
}

#endif
